package com.troday.api.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.troday.api.dto.ApiResponseDto;
import com.troday.api.entity.*;
import com.troday.api.repository.*;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.transaction.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;
import java.math.*; import java.time.*; import java.util.*;

@Service
public class BillingService {
 private final AccountService accounts; private final RentalServiceCatalogRepository catalogs; private final HouseServiceConfigRepository houseServices; private final RoomServiceSettingRepository roomServices; private final InvoiceRepository invoices; private final InvoiceItemRepository items; private final RentalHouseRepository houses; private final RoomRepository rooms; private final ContractRepository contracts; private final RoomTenantRepository roomTenants;
 public BillingService(AccountService a,RentalServiceCatalogRepository c,HouseServiceConfigRepository h,RoomServiceSettingRepository r,InvoiceRepository i,InvoiceItemRepository it,RentalHouseRepository houses,RoomRepository rooms,ContractRepository contracts,RoomTenantRepository roomTenants){accounts=a;catalogs=c;houseServices=h;roomServices=r;invoices=i;items=it;this.houses=houses;this.rooms=rooms;this.contracts=contracts;this.roomTenants=roomTenants;}
 public ApiResponseDto<?> catalog(HttpServletRequest r){accounts.authenticatedUserId(r);return ok("GET",catalogs.findAll().stream().map(this::catalogData).toList());}
 @Transactional public ApiResponseDto<?> createCatalog(HttpServletRequest r,JsonNode b){accounts.requireAdminId(r);require(b);String name=text(b,"name");if(name.isBlank()||catalogs.findByNameIgnoreCase(name).isPresent())throw conflict("Tên dịch vụ đã tồn tại");RentalServiceCatalog x=new RentalServiceCatalog();x.setName(name);x.setUnit(text(b,"unit"));x.setDefaultCalculationMethod(method(b,"defaultCalculationMethod"));return ok("POST",catalogData(catalogs.save(x)));}
 @Transactional public ApiResponseDto<?> updateCatalog(HttpServletRequest r,Long id,JsonNode b){accounts.requireAdminId(r);RentalServiceCatalog x=catalog(id);require(b);if(b.has("name")){String n=text(b,"name");catalogs.findByNameIgnoreCase(n).filter(y->!y.getId().equals(id)).ifPresent(y->{throw conflict("Tên dịch vụ đã tồn tại");});x.setName(n);}if(b.has("unit"))x.setUnit(text(b,"unit"));if(b.has("defaultCalculationMethod"))x.setDefaultCalculationMethod(method(b,"defaultCalculationMethod"));return ok("PATCH",catalogData(catalogs.save(x)));}
 public ApiResponseDto<?> houseList(HttpServletRequest r,Long hid){ownedHouse(r,hid);return ok("GET",houseServices.findByHouseId(hid).stream().map(this::houseServiceData).toList());}
 @Transactional public ApiResponseDto<?> houseCreate(HttpServletRequest r,Long hid,JsonNode b){ownedHouse(r,hid);require(b);HouseServiceConfig x=new HouseServiceConfig();x.setHouseId(hid);Long cid=longValue(b,"serviceId",null);if(cid!=null){RentalServiceCatalog c=catalog(cid);x.setCatalogServiceId(cid);x.setName(c.getName());x.setUnit(c.getUnit());x.setDefaultCalculationMethod(c.getDefaultCalculationMethod());}else{x.setName(text(b,"name"));x.setUnit(text(b,"unit"));x.setDefaultCalculationMethod(method(b,"calculationMethod"));}x.setDefaultUnitPrice(money(b,"unitPrice",BigDecimal.ZERO));x.setActive(b.has("active")?b.get("active").asBoolean():true);return ok("POST",houseServiceData(houseServices.save(x)));}
 @Transactional public ApiResponseDto<?> houseUpdate(HttpServletRequest r,Long hid,Long id,JsonNode b){ownedHouse(r,hid);HouseServiceConfig x=houseService(hid,id);require(b);if(b.has("name"))x.setName(text(b,"name"));if(b.has("unit"))x.setUnit(text(b,"unit"));if(b.has("unitPrice"))x.setDefaultUnitPrice(money(b,"unitPrice",null));if(b.has("calculationMethod"))x.setDefaultCalculationMethod(method(b,"calculationMethod"));if(b.has("active"))x.setActive(b.get("active").asBoolean());return ok("PATCH",houseServiceData(houseServices.save(x)));}
 @Transactional public ApiResponseDto<?> roomSet(HttpServletRequest r,Long rid,Long hsid,JsonNode b){Room room=ownedRoom(r,rid);HouseServiceConfig hs=houseServices.findById(hsid).orElseThrow(()->notFound("Không tìm thấy dịch vụ nhà"));if(!hs.getHouseId().equals(room.getHouseId()))throw bad("Dịch vụ không thuộc nhà của phòng");require(b);RoomServiceSetting x=roomServices.findByRoomIdAndHouseServiceId(rid,hsid).orElseGet(RoomServiceSetting::new);x.setRoomId(rid);x.setHouseId(room.getHouseId());x.setHouseServiceId(hsid);if(b.has("unitPriceOverride"))x.setUnitPriceOverride(b.get("unitPriceOverride").isNull()?null:money(b,"unitPriceOverride",null));if(b.has("calculationMethodOverride"))x.setCalculationMethodOverride(b.get("calculationMethodOverride").isNull()?null:method(b,"calculationMethodOverride"));if(b.has("active"))x.setActive(b.get("active").asBoolean());return ok("PUT",roomServiceData(x,hs));}
 public ApiResponseDto<?> roomList(HttpServletRequest r,Long rid){Room room=ownedRoom(r,rid);return ok("GET",roomServices.findByRoomId(rid).stream().map(x->roomServiceData(x,houseService(room.getHouseId(),x.getHouseServiceId()))).toList());}
 public ApiResponseDto<?> invoiceList(HttpServletRequest r,Long contractId, String period,String status){Long me=accounts.authenticatedUserId(r);return ok("GET",invoices.findAll().stream().filter(x->(contractId==null||contractId.equals(x.getContractId()))&&(period==null||period.equals(String.valueOf(x.getBillingPeriod())))&&(status==null||status.equals(x.getStatus()))).filter(x->canView(x,me)).map(this::invoiceData).toList());}
 public ApiResponseDto<?> invoiceDetail(HttpServletRequest r,Long id){Invoice x=invoice(id);canViewOrThrow(x,accounts.authenticatedUserId(r));return ok("GET",invoiceData(x));}
 @Transactional public ApiResponseDto<?> createInvoice(HttpServletRequest r,JsonNode b){require(b);Long owner=accounts.authenticatedUserId(r);Long cid=requiredLong(b,"contractId");Contract c=ownedContract(owner,cid);LocalDate period=date(b,"billingPeriod");if(period.getDayOfMonth()!=1)throw bad("billingPeriod phải là ngày đầu tháng");if(invoices.findByContractIdAndBillingPeriodAndStatusNot(cid,period,"CANCELLED").isPresent())throw conflict("Đã tồn tại hóa đơn trong kỳ");Invoice x=new Invoice();x.setContractId(cid);x.setRoomId(c.getRoomId());x.setContractRevisionId(c.getCurrentRevisionId());x.setPayerRoomTenantId(requiredLong(b,"payerRoomTenantId"));x.setBillingPeriod(period);x.setDueDate(date(b,"dueDate"));x.setCreatedById(owner);x.setOccupantCountAtBilling(occupantCount(cid));x=invoices.save(x);replaceItems(x,b);return ok("POST",invoiceData(x));}
 @Transactional public ApiResponseDto<?> updateInvoice(HttpServletRequest r,Long id,JsonNode b){Invoice x=invoice(id);ownedContract(accounts.authenticatedUserId(r),x.getContractId());if(!"DRAFT".equals(x.getStatus()))throw conflict("Chỉ hóa đơn DRAFT mới được sửa");require(b);if(b.has("dueDate"))x.setDueDate(date(b,"dueDate"));x=invoices.save(x);replaceItems(x,b);return ok("PATCH",invoiceData(x));}
 @Transactional public ApiResponseDto<?> issue(HttpServletRequest r,Long id){Invoice x=invoice(id);ownedContract(accounts.authenticatedUserId(r),x.getContractId());if(!"DRAFT".equals(x.getStatus()))throw conflict("Trạng thái hóa đơn không hợp lệ");if(items.findByInvoiceIdOrderByPosition(id).isEmpty())throw bad("Hóa đơn phải có dòng tiền");x.setStatus("UNPAID");return ok("POST",invoiceData(invoices.save(x)));}
 @Transactional public ApiResponseDto<?> pay(HttpServletRequest r,Long id){Long owner=accounts.authenticatedUserId(r);Invoice x=invoice(id);ownedContract(owner,x.getContractId());if(!"UNPAID".equals(x.getStatus())&&!"OVERDUE".equals(x.getStatus()))throw conflict("Hóa đơn chưa thể ghi nhận thanh toán");x.setStatus("PAID");x.setPaidById(owner);x.setPaidAt(LocalDateTime.now());return ok("POST",invoiceData(invoices.save(x)));}
 @Transactional public ApiResponseDto<?> cancel(HttpServletRequest r,Long id,JsonNode b){Long owner=accounts.authenticatedUserId(r);Invoice x=invoice(id);ownedContract(owner,x.getContractId());if(!Set.of("UNPAID","OVERDUE").contains(x.getStatus()))throw conflict("Chỉ hóa đơn chưa thu mới được hủy");String reason=text(b,"reason");if(reason.isBlank())throw bad("reason là bắt buộc");x.setStatus("CANCELLED");x.setCancelledById(owner);x.setCancelledAt(LocalDateTime.now());x.setCancellationReason(reason);return ok("POST",invoiceData(invoices.save(x)));}
 @Transactional public ApiResponseDto<?> replacement(HttpServletRequest r,Long id,JsonNode b){Long owner=accounts.authenticatedUserId(r);Invoice old=invoice(id);ownedContract(owner,old.getContractId());if(!"CANCELLED".equals(old.getStatus()))throw conflict("Chỉ hóa đơn đã hủy mới được thay thế");Invoice x=new Invoice();x.setContractId(old.getContractId());x.setRoomId(old.getRoomId());x.setContractRevisionId(old.getContractRevisionId());x.setPayerRoomTenantId(old.getPayerRoomTenantId());x.setBillingPeriod(old.getBillingPeriod());x.setDueDate(b!=null&&b.has("dueDate")?date(b,"dueDate"):old.getDueDate());x.setCreatedById(owner);x.setReplacementOfId(old.getId());x.setOccupantCountAtBilling(old.getOccupantCountAtBilling());x=invoices.save(x);replaceItems(x,b);return ok("POST",invoiceData(x));}
 private void replaceItems(Invoice x,JsonNode b){items.deleteByInvoiceId(x.getId());if(b==null||!b.has("items")||!b.get("items").isArray())return;int pos=0;for(JsonNode n:b.get("items")){InvoiceItem i=new InvoiceItem();i.setInvoiceId(x.getId());i.setRoomId(x.getRoomId());i.setPosition(pos++);i.setItemType(text(n,"type","OTHER"));i.setNameSnapshot(text(n,"name",i.getItemType()));i.setUnitSnapshot(text(n,"unit","unit"));i.setQuantity(decimal(n,"quantity",BigDecimal.ONE));i.setUnitPriceSnapshot(money(n,"unitPrice",BigDecimal.ZERO));i.setAmount(i.getQuantity().multiply(i.getUnitPriceSnapshot()).setScale(2,RoundingMode.HALF_UP));if("SERVICE".equals(i.getItemType())){i.setRoomServiceId(requiredLong(n,"roomServiceId"));i.setCalculationMethodSnapshot(text(n,"calculationMethod","PER_ROOM"));if("METERED".equals(i.getCalculationMethodSnapshot())){i.setPreviousReading(decimal(n,"previousReading",BigDecimal.ZERO));i.setCurrentReading(decimal(n,"currentReading",i.getPreviousReading()));i.setQuantity(i.getCurrentReading().subtract(i.getPreviousReading()));i.setAmount(i.getQuantity().multiply(i.getUnitPriceSnapshot()).setScale(2,RoundingMode.HALF_UP));}}items.save(i);}}
 private Map<String,Object> invoiceData(Invoice x){List<InvoiceItem> list=items.findByInvoiceIdOrderByPosition(x.getId());BigDecimal total=list.stream().map(InvoiceItem::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("id",x.getId(),"contractId",x.getContractId(),"roomId",x.getRoomId(),"period",x.getBillingPeriod(),"billingPeriod",x.getBillingPeriod(),"dueDate",x.getDueDate(),"status",x.getStatus(),"payerId",x.getPayerRoomTenantId(),"total",total,"items",list.stream().map(this::itemData).toList());}
 private Map<String,Object> itemData(InvoiceItem x){Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.getId());m.put("type",x.getItemType());m.put("name",x.getNameSnapshot());m.put("quantity",x.getQuantity());m.put("unitPrice",x.getUnitPriceSnapshot());m.put("amount",x.getAmount());m.put("roomServiceId",x.getRoomServiceId());return m;}
 private Map<String,Object> catalogData(RentalServiceCatalog x){return Map.of("id",x.getId(),"name",x.getName(),"unit",x.getUnit(),"defaultCalculationMethod",x.getDefaultCalculationMethod());}
 private Map<String,Object> houseServiceData(HouseServiceConfig x){return Map.of("id",x.getId(),"houseId",x.getHouseId(),"serviceId",Objects.toString(x.getCatalogServiceId(),""),"name",x.getName(),"unit",x.getUnit(),"unitPrice",x.getDefaultUnitPrice(),"calculationMethod",x.getDefaultCalculationMethod(),"active",x.getActive());}
 private Map<String,Object> roomServiceData(RoomServiceSetting x,HouseServiceConfig h){return Map.of("id",x.getId(),"roomId",x.getRoomId(),"houseServiceId",x.getHouseServiceId(),"active",x.getActive(),"effectiveUnitPrice",x.getUnitPriceOverride()!=null?x.getUnitPriceOverride():h.getDefaultUnitPrice(),"unitPriceOverride",Objects.toString(x.getUnitPriceOverride(),""),"calculationMethod",x.getCalculationMethodOverride()!=null?x.getCalculationMethodOverride():h.getDefaultCalculationMethod());}
 private RentalServiceCatalog catalog(Long id){return catalogs.findById(id).orElseThrow(()->notFound("Không tìm thấy danh mục dịch vụ"));} private HouseServiceConfig houseService(Long hid,Long id){return houseServices.findByIdAndHouseId(id,hid).orElseThrow(()->notFound("Không tìm thấy dịch vụ nhà"));} private Invoice invoice(Long id){return invoices.findById(id).orElseThrow(()->notFound("Không tìm thấy hóa đơn"));}
 private RentalHouse ownedHouse(HttpServletRequest r,Long id){RentalHouse h=houses.findById(id).orElseThrow(()->notFound("Không tìm thấy nhà"));if(!Objects.equals(h.getLandlordId(),accounts.authenticatedUserId(r)))throw forbidden("Bạn không sở hữu nhà này");return h;} private Room ownedRoom(HttpServletRequest r,Long id){Room x=rooms.findById(id).orElseThrow(()->notFound("Không tìm thấy phòng"));ownedHouse(r,x.getHouseId());return x;} private Contract ownedContract(Long owner,Long id){Contract c=contracts.findById(id).orElseThrow(()->notFound("Không tìm thấy hợp đồng"));if(!Objects.equals(c.getLandlordId(),owner))throw forbidden("Bạn không sở hữu hợp đồng");return c;} private boolean canView(Invoice x,Long me){Contract c=contracts.findById(x.getContractId()).orElse(null);return c!=null&&(Objects.equals(c.getLandlordId(),me)||Objects.equals(c.getViewingTenantId(),me)||roomTenants.findAll().stream().anyMatch(t->Objects.equals(t.getId(),x.getPayerRoomTenantId())&&Objects.equals(t.getTenantId(),me)));} private void canViewOrThrow(Invoice x,Long me){if(!canView(x,me))throw forbidden("Không có quyền xem hóa đơn");} private int occupantCount(Long cid){return (int)roomTenants.findAll().stream().filter(x->Objects.equals(x.getContractId(),cid)&&!"CANCELLED".equals(x.getStatus())).count();}
 private ApiResponseDto<?> ok(String method,Object data){return ApiResponseDto.ok("/api/v1",method,data);} private void require(JsonNode b){if(b==null||!b.isObject())throw bad("JSON request là bắt buộc");} private String text(JsonNode b,String k){return text(b,k,"");} private String text(JsonNode b,String k,String f){return b!=null&&b.hasNonNull(k)?b.get(k).asText():f;} private Long requiredLong(JsonNode b,String k){return longValue(b,k,null)!=null?longValue(b,k,null):throwBad(k+" là bắt buộc");} private Long longValue(JsonNode b,String k,Long f){try{return b!=null&&b.hasNonNull(k)?b.get(k).asLong():f;}catch(Exception e){throw bad(k+" không hợp lệ");}} private BigDecimal decimal(JsonNode b,String k,BigDecimal f){try{return b!=null&&b.hasNonNull(k)?new BigDecimal(b.get(k).asText()):f;}catch(Exception e){throw bad(k+" không hợp lệ");}} private BigDecimal money(JsonNode b,String k,BigDecimal f){BigDecimal x=decimal(b,k,f);if(x!=null&&x.signum()<0)throw bad(k+" không được âm");return x;} private LocalDate date(JsonNode b,String k){try{return LocalDate.parse(text(b,k));}catch(Exception e){throw bad(k+" không hợp lệ");}} private String method(JsonNode b,String k){String x=text(b,k);if(!Set.of("METERED","PER_PERSON","PER_ROOM").contains(x))throw bad(k+" không hợp lệ");return x;} private <T>T throwBad(String m){throw bad(m);} private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);} private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);} private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);} private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
